package com.garmentstore.auth.domain;
import com.garmentstore.common.domain.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*;
@Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor @Entity @Table(name="users", indexes={@Index(name="idx_users_email",columnList="email"),@Index(name="idx_users_mobile",columnList="mobile"),@Index(name="idx_users_status",columnList="account_status")}) public class User extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Enumerated(EnumType.STRING) @Column(name="user_type",nullable=false,length=30) private UserType userType; @Column(name="name",length=150) private String name; @Column(name="email",length=180,unique=true) private String email; @Column(name="mobile",length=20,unique=true) private String mobile; @Column(name="password_hash",nullable=false,length=255) private String passwordHash; @Enumerated(EnumType.STRING) @Column(name="account_status",nullable=false,length=40) private AccountStatus accountStatus; @Column(name="email_verified",nullable=false) private boolean emailVerified; @Column(name="mobile_verified",nullable=false) private boolean mobileVerified; @Column(name="last_login_at") private Instant lastLoginAt; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="user_roles", joinColumns=@JoinColumn(name="user_id"), inverseJoinColumns=@JoinColumn(name="role_id")) private Set<Role> roles=new HashSet<>(); }
